/**
 * Real Good AI donation widgets: the core Web Components (oss/donation-widgets) extended with
 * campaigns. Importing this module defines <rg-donation-form>, <rg-leaderboard> and
 * <rg-recent-donations>; use them as plain elements, no mount helpers needed.
 */
import { RgDonationForm } from './rg-donation-form';
import { RgLeaderboard } from './rg-leaderboard';
import { RgRecentDonations } from './rg-recent-donations';

export { RgDonationForm, RgLeaderboard, RgRecentDonations };

if (!customElements.get('rg-donation-form')) customElements.define('rg-donation-form', RgDonationForm);
if (!customElements.get('rg-leaderboard')) customElements.define('rg-leaderboard', RgLeaderboard);
if (!customElements.get('rg-recent-donations')) customElements.define('rg-recent-donations', RgRecentDonations);
