import { escapeHtml } from './lib/format';
import { type LeaderboardRow, rankingArgs, renderLeaderboardRows } from './leaderboard-render';
import { LiveWidget } from './live-widget';
import { leaderboardStyles } from './styles/leaderboard';

const TIMEFRAMES: ReadonlyArray<{ days: number; label: string }> = [
  { days: 30, label: '30d' },
  { days: 90, label: '3mo' },
  { days: 180, label: '6mo' },
  { days: 365, label: '1yr' },
  { days: 0, label: 'All' },
];
const DEFAULT_DAYS = 180;
const DEFAULT_LIMIT = 10;

/**
 * <dw-leaderboard>: top supporters, with a timeframe selector and live updates.
 *
 * Attributes: `supabase-url`, `supabase-key` (the publishable key), and optionally
 * `title`, `subtitle`, `limit` (rows shown, default 10).
 *
 * Extension points: `leaderboardArgs()` (extra arguments for the `leaderboard_rankings`
 * function), `realtimeFilters()` and `getSupabase()`.
 */
export class DwLeaderboard extends LiveWidget {
  static get observedAttributes(): string[] {
    return super.observedAttributes;
  }

  private activeDays = DEFAULT_DAYS;
  private requestSeq = 0;

  constructor() {
    super(leaderboardStyles);
    this.root.addEventListener('click', (e) => {
      const btn = (e.target as HTMLElement).closest<HTMLElement>('.lb-tf');
      if (!btn) return;
      this.activeDays = parseInt(btn.dataset.days ?? String(DEFAULT_DAYS), 10);
      this.markActiveTimeframe();
      this.setList('<li class="lb-state">Loading…</li>');
      void this.refresh();
    });
  }

  /** Extra arguments for `leaderboard_rankings` (for example a campaign filter). Default: none. */
  protected leaderboardArgs(): Record<string, unknown> {
    return {};
  }

  protected channelPrefix(): string {
    return 'dw-leaderboard';
  }

  protected render(): void {
    const title = this.getAttribute('title') ?? 'Top Supporters';
    const subtitle = this.getAttribute('subtitle') ?? 'Cumulative giving · live updates';
    this.setHtml(`
      <div class="lb-wrap" part="wrap">
        <div class="lb-header">
          <div class="lb-title-row">
            <span class="lb-trophy" aria-hidden="true">🏆</span>
            <div>
              <h3 class="lb-title">${escapeHtml(title)}</h3>
              <p class="lb-subtitle">${escapeHtml(subtitle)}</p>
            </div>
            <span class="lb-live-dot" title="Live data"></span>
          </div>
          <div class="lb-timeframes" role="group" aria-label="Timeframe">
            ${TIMEFRAMES.map((t) => `<button type="button" class="lb-tf" data-days="${t.days}">${t.label}</button>`).join('')}
          </div>
        </div>
        <ol class="lb-list" aria-live="polite" aria-label="Leaderboard"><li class="lb-state">Loading…</li></ol>
      </div>`);
    this.markActiveTimeframe();
  }

  private markActiveTimeframe(): void {
    this.$$('.lb-tf').forEach((b) => b.classList.toggle('lb-tf--active', Number(b.dataset.days) === this.activeDays));
  }

  private setList(html: string): void {
    const list = this.$('.lb-list');
    if (list) list.innerHTML = html;
  }

  protected showError(message: string): void {
    this.setList(`<li class="lb-state lb-error">${escapeHtml(message)}</li>`);
  }

  protected async refresh(): Promise<void> {
    const seq = ++this.requestSeq;
    const limit = Number(this.getAttribute('limit')) || DEFAULT_LIMIT;
    try {
      const { data, error } = await this.getSupabase().rpc(
        'leaderboard_rankings',
        rankingArgs(this.activeDays, limit, this.leaderboardArgs()),
      );
      if (seq !== this.requestSeq) return; // a newer request superseded this one
      if (error) throw error;
      this.setList(renderLeaderboardRows(data as LeaderboardRow[]));
    } catch (err) {
      if (seq !== this.requestSeq) return;
      console.error('Leaderboard error:', err);
      this.showError('Could not load leaderboard. Please refresh.');
    }
  }
}
