import { DwDonationForm } from '../../oss/donation-widgets/src/donation-form';
import { resolveSupabaseUrl } from '../common/runtime-config';
import { checkoutContextFor, parseCampaignSlug } from '../common/campaign-filters';

/**
 * <rg-donation-form campaign-slug="…">: the Real Good AI donation form.
 *
 * The core form plus: the donation is attributed to a campaign (the slug travels as
 * `context.campaignSlug`; the server resolves it to an active campaign), the checkout URL
 * defaults to this environment's create-checkout function, and the newsletter checkbox is on
 * (`newsletter="false"` turns it off).
 */
export class RgDonationForm extends DwDonationForm {
  static get observedAttributes(): string[] {
    return [...super.observedAttributes, 'campaign-slug'];
  }

  protected override checkoutContext(): unknown {
    return checkoutContextFor(parseCampaignSlug(this.getAttribute('campaign-slug')));
  }

  protected override checkoutUrl(): string {
    return this.getAttribute('checkout-url') || `${resolveSupabaseUrl()}/functions/v1/create-checkout`;
  }

  protected override newsletterEnabled(): boolean {
    return this.getAttribute('newsletter')?.trim().toLowerCase() !== 'false';
  }
}
