import { BaseElement } from './lib/base-element';
import { escapeHtml } from './lib/format';
import { donationFormStyles } from './styles/donation-form';
import {
  buildPayload,
  type Currency,
  type DonationState,
  effectiveAmount,
  initialState,
  type Interval,
  isFlagOn,
  noteHtml,
  parseAmounts,
  parseCurrencies,
  pickDefaultAmount,
  selectPreset,
  setCurrency,
  setCustomAmount,
  submitLabel,
} from './donation-state';

const DEFAULT_TITLE = 'Make a Donation';
const DEFAULT_SUBTITLE = 'Every dollar supports our mission';

/**
 * <dw-donation-form>: a donation form that posts to a `create-checkout` function and redirects
 * to the Stripe Checkout URL it returns.
 *
 * Attributes (all optional except `checkout-url`):
 *   checkout-url     where to POST the request
 *   newsletter       show the "Sign me up for the newsletter" checkbox (off by default)
 *   amounts          preset amounts, e.g. "5,10,20,50,100"
 *   default-amount   the preselected preset, e.g. "20"
 *   currencies       offered currencies in order, e.g. "usd,eur" (usd, eur, gbp, cad, aud)
 *   title, subtitle  text of the dark header
 *
 * Event: `dw-donate-attempt` (cancelable, bubbles, composed) is fired with the request body
 * before anything is sent. Call `preventDefault()` to stop the request.
 *
 * To extend it, subclass and override `checkoutContext()`, `checkoutUrl()` or
 * `newsletterEnabled()`; see the README ("Extending the widgets").
 */
export class DwDonationForm extends BaseElement {
  static get observedAttributes(): string[] {
    return ['checkout-url', 'newsletter', 'amounts', 'default-amount', 'currencies', 'title', 'subtitle'];
  }

  protected state: DonationState = initialState({ code: 'usd', sym: '$', label: 'USD' }, 20);
  private amounts: number[] = [];
  private currencies: Currency[] = [];
  private loading = false;
  private errorMessage = '';
  private rendered = false;

  constructor() {
    super(donationFormStyles);
    this.root.addEventListener('click', (e) => this.onClick(e));
    this.root.addEventListener('input', (e) => this.onInput(e));
    this.root.addEventListener('change', (e) => this.onChange(e));
  }

  connectedCallback(): void {
    this.configure();
    this.render();
  }

  attributeChangedCallback(): void {
    if (!this.isConnected) return;
    this.configure();
    this.render();
  }

  // ── Extension points ──────────────────────────────────────────────────────

  /** Extra data sent as `context` in the request body (any JSON, at most 2 KB). Default: none. */
  protected checkoutContext(): unknown {
    return undefined;
  }

  /** The URL the request is POSTed to. Default: the `checkout-url` attribute. */
  protected checkoutUrl(): string {
    return this.getAttribute('checkout-url') ?? '';
  }

  /** Whether the newsletter checkbox is shown. Default: the `newsletter` attribute. */
  protected newsletterEnabled(): boolean {
    return isFlagOn(this.getAttribute('newsletter'));
  }

  // ── Setup ─────────────────────────────────────────────────────────────────

  /** Read the attributes into `amounts`/`currencies` and keep the state consistent with them. */
  private configure(): void {
    this.amounts = parseAmounts(this.getAttribute('amounts'));
    this.currencies = parseCurrencies(this.getAttribute('currencies'));

    if (!this.rendered) {
      this.state = initialState(this.currencies[0], pickDefaultAmount(this.amounts, this.getAttribute('default-amount')));
      return;
    }
    // Reconfigured while on screen: keep the donor's input, repair what no longer exists.
    if (!this.currencies.some((c) => c.code === this.state.currency)) {
      this.state = setCurrency(this.state, this.currencies[0]);
    }
    if (this.state.amount !== null && !this.amounts.includes(this.state.amount)) {
      this.state = { ...this.state, amount: pickDefaultAmount(this.amounts, null) };
    }
  }

  private render(): void {
    const title = this.getAttribute('title') ?? DEFAULT_TITLE;
    const subtitle = this.getAttribute('subtitle') ?? DEFAULT_SUBTITLE;
    const newsletter = this.newsletterEnabled();

    this.setHtml(`
      <div class="dw-wrap" id="dw-root" part="wrap">
        <div class="dw-header">
          <p class="dw-header-title">${escapeHtml(title)}</p>
          <p class="dw-header-subtitle">${escapeHtml(subtitle)}</p>
        </div>
        <div class="dw-body">
          <div class="dw-section">
            <p class="dw-label">Donation amount</p>
            <div class="dw-amounts" id="dw-amounts" style="grid-template-columns: repeat(${this.amounts.length}, 1fr)">
              ${this.amounts.map((v) => `<button type="button" class="dw-amt" data-val="${v}"></button>`).join('')}
            </div>
            <div class="dw-custom-row">
              <span class="dw-sym" id="dw-sym"></span>
              <input class="dw-input" type="number" id="dw-custom" placeholder="Other amount" min="1" step="1" aria-label="Custom donation amount" value="${escapeHtml(this.state.customAmount)}" />
            </div>
          </div>
          <div class="dw-section">
            <p class="dw-label">Frequency</p>
            <div class="dw-toggle">
              <button type="button" class="dw-tog" data-rec="false">Give once</button>
              <button type="button" class="dw-tog" data-rec="true">Give regularly</button>
            </div>
            <div class="dw-freq-row" id="dw-freq-row">
              <button type="button" class="dw-frq" data-frq="week">Weekly</button>
              <button type="button" class="dw-frq" data-frq="month">Monthly</button>
              <button type="button" class="dw-frq" data-frq="year">Yearly</button>
            </div>
          </div>
          <div class="dw-section">
            <p class="dw-label">Currency</p>
            <div class="dw-currencies" id="dw-currencies">
              ${this.currencies.map((c) => `<button type="button" class="dw-cur" data-cur="${c.code}">${c.label}</button>`).join('')}
            </div>
          </div>
          <div class="dw-section">
            <label class="dw-label" for="dw-name">Your name on the leaderboard <span class="dw-optional">(optional)</span></label>
            <input class="dw-input" type="text" id="dw-name" placeholder="Leave blank to donate anonymously" maxlength="60" value="${escapeHtml(this.state.name)}" />
          </div>
          ${
            newsletter
              ? `<div class="dw-section dw-checkbox-row" id="dw-newsletter-row">
            <label class="dw-checkbox-label"><input type="checkbox" id="dw-newsletter" ${this.state.newsletterOptIn ? 'checked' : ''} /><span>Sign me up for the newsletter</span></label>
          </div>`
              : ''
          }
          <button type="button" class="dw-submit" id="dw-submit" aria-live="polite"></button>
          <p class="dw-note" id="dw-note"></p>
          <p class="dw-error" id="dw-error" role="alert" aria-live="assertive"></p>
        </div>
      </div>`);

    this.rendered = true;
    this.updateUI();
  }

  /** Bring every changing part of the markup in line with `this.state`. */
  private updateUI(): void {
    const s = this.state;
    const amt = effectiveAmount(s);
    const text = (sel: string, value: string) => {
      const el = this.$(sel);
      if (el) el.textContent = value;
    };

    const submit = this.$<HTMLButtonElement>('#dw-submit');
    if (submit) {
      submit.textContent = submitLabel(s, this.loading);
      submit.disabled = this.loading || amt === null || amt < 1;
    }
    const note = this.$('#dw-note');
    if (note) note.innerHTML = noteHtml(s);

    const freqRow = this.$('#dw-freq-row');
    if (freqRow) {
      freqRow.style.display = s.recurring ? 'flex' : 'none';
      freqRow.setAttribute('aria-hidden', String(!s.recurring));
    }

    text('#dw-sym', s.sym);
    text('#dw-error', this.errorMessage);

    this.$$('.dw-amt').forEach((b) => {
      const val = Number(b.dataset.val);
      b.textContent = `${s.sym}${val}`;
      b.classList.toggle('dw-amt--active', s.customAmount === '' && s.amount === val);
    });
    this.$$('.dw-tog').forEach((b) => b.classList.toggle('dw-tog--active', (b.dataset.rec === 'true') === s.recurring));
    this.$$('.dw-frq').forEach((b) => b.classList.toggle('dw-frq--active', b.dataset.frq === s.interval));
    this.$$('.dw-cur').forEach((b) => b.classList.toggle('dw-cur--active', b.dataset.cur === s.currency));
  }

  // ── Events ────────────────────────────────────────────────────────────────

  private onClick(e: Event): void {
    const target = e.target as HTMLElement | null;
    const btn = target?.closest<HTMLElement>('button');
    if (!btn) return;
    this.errorMessage = '';

    if (btn.classList.contains('dw-amt')) {
      this.state = selectPreset(this.state, Number(btn.dataset.val));
      const custom = this.$<HTMLInputElement>('#dw-custom');
      if (custom) custom.value = '';
    } else if (btn.classList.contains('dw-tog')) {
      this.state = { ...this.state, recurring: btn.dataset.rec === 'true' };
    } else if (btn.classList.contains('dw-frq')) {
      this.state = { ...this.state, interval: (btn.dataset.frq as Interval) ?? 'month' };
    } else if (btn.classList.contains('dw-cur')) {
      const currency = this.currencies.find((c) => c.code === btn.dataset.cur);
      if (currency) this.state = setCurrency(this.state, currency);
    } else if (btn.id === 'dw-submit') {
      void this.handleSubmit();
      return;
    } else {
      return;
    }
    this.updateUI();
  }

  private onInput(e: Event): void {
    const input = e.target as HTMLInputElement;
    if (input.id === 'dw-custom') {
      this.errorMessage = '';
      this.state = setCustomAmount(this.state, input.value);
      this.updateUI();
    } else if (input.id === 'dw-name') {
      this.state = { ...this.state, name: input.value };
    }
  }

  private onChange(e: Event): void {
    const input = e.target as HTMLInputElement;
    if (input.id === 'dw-newsletter') this.state = { ...this.state, newsletterOptIn: input.checked };
  }

  private async handleSubmit(): Promise<void> {
    if (this.loading) return;

    const payload = buildPayload(this.state);
    if (!payload) {
      this.errorMessage = 'Please enter an amount of at least 1.00.';
      this.updateUI();
      return;
    }
    // Never send an opt-in the donor could not have seen.
    if (!this.newsletterEnabled()) payload.newsletterOptIn = false;

    const url = this.checkoutUrl();
    if (!url) {
      this.errorMessage = 'This donation form is not configured (missing checkout-url).';
      this.updateUI();
      return;
    }

    const context = this.checkoutContext();
    const body = context === undefined ? payload : { ...payload, context };

    if (!this.emit('dw-donate-attempt', body, { cancelable: true })) return;

    this.loading = true;
    this.errorMessage = '';
    this.updateUI();

    try {
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const data = (await res.json()) as { url?: string; error?: string };
      if (!res.ok || !data.url) throw new Error(data.error || 'Something went wrong. Please try again.');
      window.location.href = data.url;
    } catch (err) {
      this.errorMessage = err instanceof Error ? err.message : 'Could not connect. Please try again.';
      this.loading = false;
      this.updateUI();
    }
  }
}
