import { createClient, type SupabaseClient } from '@supabase/supabase-js';

const clients = new Map<string, SupabaseClient>();

/**
 * One Supabase client per (url, key) pair, shared by every widget on the page, so a page
 * with a leaderboard and a recent-donations feed opens a single realtime socket.
 * Throws a readable error when the attributes are missing.
 */
export function getSharedClient(url: string | null, key: string | null): SupabaseClient {
  if (!url || !key) {
    throw new Error('Missing supabase-url or supabase-key attribute on the widget.');
  }
  const id = `${url}|${key}`;
  let client = clients.get(id);
  if (!client) {
    // No auth: the widgets only read public data with the publishable key.
    client = createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false } });
    clients.set(id, client);
  }
  return client;
}
