import type { SupabaseClient, RealtimeChannel } from '@supabase/supabase-js';
import { BaseElement } from './lib/base-element';
import { getSharedClient } from './lib/supabase';

/**
 * Shared behavior of the two read-only widgets (<dw-leaderboard>, <dw-recent-donations>):
 * a Supabase client from the `supabase-url` / `supabase-key` attributes, a live subscription to
 * changes of the `donations` table, and a debounced refresh.
 *
 * Subclasses implement `refresh()` and may override `getSupabase()` and `realtimeFilters()`.
 */
export abstract class LiveWidget extends BaseElement {
  static get observedAttributes(): string[] {
    return ['supabase-url', 'supabase-key', 'title', 'subtitle', 'limit'];
  }

  private channel: RealtimeChannel | null = null;
  private client: SupabaseClient | null = null;
  private debounce: ReturnType<typeof setTimeout> | undefined;
  private started = false;
  private static nextId = 1;
  private readonly instanceId = LiveWidget.nextId++;

  /** Build the markup (once per connect or attribute change). */
  protected abstract render(): void;

  /** Fetch the data and draw it. Must handle its own errors. */
  protected abstract refresh(): Promise<void>;

  /** Prefix of the realtime channel name. */
  protected abstract channelPrefix(): string;

  // ── Extension points ──────────────────────────────────────────────────────

  /** The Supabase client. Default: a shared one built from the `supabase-url` / `supabase-key` attributes. */
  protected getSupabase(): SupabaseClient {
    return getSharedClient(this.getAttribute('supabase-url'), this.getAttribute('supabase-key'));
  }

  /**
   * Realtime row filters, e.g. `["campaign_id=eq.<uuid>"]`. One subscription is made per filter.
   * An empty array (the default) subscribes to every change of the `donations` table.
   */
  protected realtimeFilters(): string[] {
    return [];
  }

  /**
   * Also refresh when ANY row of `donations` is deleted. Postgres cannot filter deletions, so a
   * widget with `realtimeFilters()` is otherwise not told about a full refund. Default: false
   * (an unfiltered widget already hears every change).
   */
  protected watchDeletes(): boolean {
    return false;
  }

  // ── Lifecycle ─────────────────────────────────────────────────────────────

  connectedCallback(): void {
    this.start();
  }

  disconnectedCallback(): void {
    this.started = false;
    this.stop();
  }

  attributeChangedCallback(): void {
    // Attributes arrive before connectedCallback during parsing; only react once running.
    if (this.started) this.start();
  }

  /** (Re)build the markup, reconnect the subscription and load fresh data. */
  protected start(): void {
    this.started = true;
    this.stop();
    this.render();
    try {
      this.client = this.getSupabase();
    } catch (err) {
      this.client = null;
      this.showError(err instanceof Error ? err.message : 'Could not start.');
      return;
    }
    this.subscribe();
    void this.refresh();
  }

  protected stop(): void {
    clearTimeout(this.debounce);
    if (this.channel && this.client) void this.client.removeChannel(this.channel);
    this.channel = null;
  }

  /** Subclasses draw an error where the list goes. */
  protected abstract showError(message: string): void;

  /** Called on every database change: coalesces bursts into one refresh. */
  protected scheduleRefresh(): void {
    clearTimeout(this.debounce);
    this.debounce = setTimeout(() => void this.refresh(), 250);
  }

  private subscribe(): void {
    if (!this.client) return;
    const filters = this.realtimeFilters();
    const channel = this.client.channel(`${this.channelPrefix()}-${this.instanceId}`);
    for (const filter of filters.length ? filters : [undefined]) {
      channel.on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'donations', ...(filter ? { filter } : {}) },
        () => this.scheduleRefresh(),
      );
    }
    if (this.watchDeletes()) {
      channel.on('postgres_changes', { event: 'DELETE', schema: 'public', table: 'donations' }, () => this.scheduleRefresh());
    }
    channel.subscribe();
    this.channel = channel;
  }
}
