import type { PostgrestFilterBuilder } from '@supabase/supabase-js';
import { escapeHtml } from './lib/format';
import { RECENT_COLUMNS, type RecentRow, renderRecentRows } from './recent-render';
import { LiveWidget } from './live-widget';
import { recentDonationsStyles } from './styles/recent-donations';

/**
 * The query a subclass can narrow in `recentQuery()`: `from('donations').select(...)`, before
 * order and limit are applied. Loosely typed on purpose: the exact type depends on a database
 * schema the widgets do not have.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type RecentQuery = PostgrestFilterBuilder<any, any, any, any, any, any, any, any>;

const DEFAULT_LIMIT = 10;
const REFRESH_EVERY_MS = 60_000;

/**
 * <dw-recent-donations>: the latest donations, updated live.
 *
 * Attributes: `supabase-url`, `supabase-key` (the publishable key), and optionally
 * `title`, `subtitle`, `limit` (rows shown, default 10).
 *
 * Extension points: `recentQuery()` (narrow the query), `realtimeFilters()` and `getSupabase()`.
 */
export class DwRecentDonations extends LiveWidget {
  static get observedAttributes(): string[] {
    return super.observedAttributes;
  }

  private requestSeq = 0;
  private ticker: ReturnType<typeof setInterval> | undefined;

  constructor() {
    super(recentDonationsStyles);
  }

  /** Narrow the query (for example `query.eq('campaign_id', id)`). Default: unchanged. */
  protected recentQuery(query: RecentQuery): RecentQuery {
    return query;
  }

  protected channelPrefix(): string {
    return 'dw-recent-donations';
  }

  protected render(): void {
    const title = this.getAttribute('title') ?? 'Recent Donations';
    const subtitle = this.getAttribute('subtitle') ?? 'Latest gifts · live updates';
    this.setHtml(`
      <div class="rd-wrap" part="wrap">
        <div class="rd-header">
          <div class="rd-title-row">
            <span class="rd-bolt" aria-hidden="true">⚡</span>
            <div>
              <h3 class="rd-title">${escapeHtml(title)}</h3>
              <p class="rd-subtitle">${escapeHtml(subtitle)}</p>
            </div>
            <span class="rd-live-dot" title="Live data"></span>
          </div>
        </div>
        <ol class="rd-list" aria-live="polite" aria-label="Recent donations"><li class="rd-state">Loading…</li></ol>
      </div>`);
  }

  protected override start(): void {
    super.start();
    // Also refresh once a minute: it keeps "5m ago" honest, and catches deletions (refunds),
    // which a filtered realtime subscription is not told about.
    clearInterval(this.ticker);
    this.ticker = setInterval(() => void this.refresh(), REFRESH_EVERY_MS);
  }

  protected override stop(): void {
    clearInterval(this.ticker);
    super.stop();
  }

  private setList(html: string): void {
    const list = this.$('.rd-list');
    if (list) list.innerHTML = html;
  }

  protected showError(message: string): void {
    this.setList(`<li class="rd-state rd-error">${escapeHtml(message)}</li>`);
  }

  protected async refresh(): Promise<void> {
    const seq = ++this.requestSeq;
    const limit = Number(this.getAttribute('limit')) || DEFAULT_LIMIT;
    try {
      const base = this.getSupabase().from('donations').select(RECENT_COLUMNS) as unknown as RecentQuery;
      const { data, error } = await this.recentQuery(base)
        .order('created_at', { ascending: false })
        .limit(limit);
      if (seq !== this.requestSeq) return;
      if (error) throw error;
      this.setList(renderRecentRows(data as unknown as RecentRow[]));
    } catch (err) {
      if (seq !== this.requestSeq) return;
      console.error('Recent donations error:', err);
      this.showError('Could not load recent donations. Please refresh.');
    }
  }
}
