/**
 * BaseElement: a small Web Component base class.
 * Open Shadow DOM, scoped stylesheet adoption, query helpers and bubbling events.
 */
export abstract class BaseElement extends HTMLElement {
  protected root: ShadowRoot;
  /** Stylesheet text kept for browsers without constructable stylesheets (see setHtml). */
  private fallbackCss = '';

  constructor(styles?: string) {
    super();
    this.root = this.attachShadow({ mode: 'open' });
    if (styles) this.adoptStyles(styles);
  }

  /** Adopt a CSS string into this element's Shadow DOM. */
  protected adoptStyles(css: string): void {
    if ('adoptedStyleSheets' in Document.prototype && 'replaceSync' in CSSStyleSheet.prototype) {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(css);
      this.root.adoptedStyleSheets = [...this.root.adoptedStyleSheets, sheet];
    } else {
      // No constructable stylesheets: keep the CSS so setHtml() can put it back after a re-render.
      this.fallbackCss += css;
      const styleEl = document.createElement('style');
      styleEl.textContent = css;
      this.root.appendChild(styleEl);
    }
  }

  /** Replace the shadow root's content, keeping the styles (also when they had to be a <style> element). */
  protected setHtml(html: string): void {
    this.root.innerHTML = this.fallbackCss ? `<style>${this.fallbackCss}</style>${html}` : html;
  }

  protected $<T extends HTMLElement = HTMLElement>(selector: string): T | null {
    return this.root.querySelector<T>(selector);
  }

  protected $$<T extends HTMLElement = HTMLElement>(selector: string): NodeListOf<T> {
    return this.root.querySelectorAll<T>(selector);
  }

  /**
   * Dispatch a custom event that bubbles out of the Shadow DOM (`composed`).
   * Returns false if a listener called `preventDefault()` on a cancelable event.
   */
  protected emit<T = unknown>(name: string, detail?: T, options?: CustomEventInit): boolean {
    return this.dispatchEvent(new CustomEvent(name, { bubbles: true, composed: true, detail, ...options }));
  }
}
