// The donation form's state and the rules around it, as plain functions so they can be unit-tested
// without a DOM. The component (donation-form.ts) holds a DonationState and renders from it.

export type Interval = 'week' | 'month' | 'year';

export interface Currency {
  code: string;
  sym: string;
  label: string;
}

/** Currencies the create-checkout function accepts, in display order. */
export const ALL_CURRENCIES: readonly Currency[] = [
  { code: 'usd', sym: '$', label: 'USD' },
  { code: 'eur', sym: '€', label: 'EUR' },
  { code: 'gbp', sym: '£', label: 'GBP' },
  { code: 'cad', sym: '$', label: 'CAD' },
  { code: 'aud', sym: '$', label: 'AUD' },
];

export const DEFAULT_AMOUNTS: readonly number[] = [5, 10, 20, 50, 100];
export const DEFAULT_DONATION = 20;
export const MIN_AMOUNT = 1;

export interface DonationState {
  /** The selected preset, or null if none is. */
  amount: number | null;
  /** Text of the "other amount" box; wins over `amount` when non-empty. */
  customAmount: string;
  currency: string;
  sym: string;
  recurring: boolean;
  interval: Interval;
  name: string;
  newsletterOptIn: boolean;
}

/** The JSON body sent to create-checkout (plus `context` when a subclass provides one). */
export interface CheckoutPayload {
  amount: number;
  currency: string;
  displayName?: string;
  recurring: boolean;
  interval?: Interval;
  newsletterOptIn: boolean;
}

export function initialState(currency: Currency, amount: number | null): DonationState {
  return {
    amount,
    customAmount: '',
    currency: currency.code,
    sym: currency.sym,
    recurring: false,
    interval: 'month',
    name: '',
    newsletterOptIn: false,
  };
}

/** The amount to charge: the custom box if it has text, else the selected preset. null if unusable. */
export function effectiveAmount(s: DonationState): number | null {
  if (s.customAmount !== '') {
    const parsed = parseFloat(s.customAmount);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return s.amount;
}

export function isValidAmount(amount: number | null): amount is number {
  return amount !== null && Number.isFinite(amount) && amount >= MIN_AMOUNT;
}

export function selectPreset(s: DonationState, amount: number): DonationState {
  return { ...s, amount, customAmount: '' };
}

/** Typing in the custom box deselects the preset. */
export function setCustomAmount(s: DonationState, text: string): DonationState {
  return { ...s, customAmount: text };
}

export function setCurrency(s: DonationState, currency: Currency): DonationState {
  return { ...s, currency: currency.code, sym: currency.sym };
}

/** Text of the submit button. */
export function submitLabel(s: DonationState, loading: boolean): string {
  if (loading) return 'Redirecting…';
  const amt = effectiveAmount(s);
  return `Donate ${amt ? s.sym + amt : '—'}`;
}

/** Note under the submit button (contains the `&middot;` entity, so it is HTML). */
export function noteHtml(s: DonationState): string {
  return s.recurring
    ? `Recurring &middot; billed every ${s.interval} &middot; Stripe`
    : 'One-time &middot; Processed securely by Stripe';
}

/** Build the request body, or null if the amount is not donatable. */
export function buildPayload(s: DonationState): CheckoutPayload | null {
  const amount = effectiveAmount(s);
  if (!isValidAmount(amount)) return null;
  return {
    amount,
    currency: s.currency,
    displayName: s.name.trim() || undefined,
    recurring: s.recurring,
    interval: s.recurring ? s.interval : undefined,
    newsletterOptIn: s.newsletterOptIn,
  };
}

// ── Attribute parsing ───────────────────────────────────────────────────────

/** "5, 10,20" -> [5, 10, 20]. Keeps positive whole numbers only; falls back to the defaults. */
export function parseAmounts(attr: string | null): number[] {
  if (!attr) return [...DEFAULT_AMOUNTS];
  const parsed = attr
    .split(',')
    .map((part) => Number(part.trim()))
    .filter((n) => Number.isInteger(n) && n >= MIN_AMOUNT);
  return parsed.length ? parsed : [...DEFAULT_AMOUNTS];
}

/** "usd,eur" -> [USD, EUR]. Unknown codes are ignored; falls back to all currencies. */
export function parseCurrencies(attr: string | null): Currency[] {
  if (!attr) return [...ALL_CURRENCIES];
  const picked: Currency[] = [];
  for (const raw of attr.split(',')) {
    const found = ALL_CURRENCIES.find((c) => c.code === raw.trim().toLowerCase());
    if (found && !picked.includes(found)) picked.push(found);
  }
  return picked.length ? picked : [...ALL_CURRENCIES];
}

/** The preselected preset: the requested one if it exists, else 20 if offered, else the middle one. */
export function pickDefaultAmount(amounts: readonly number[], requested: string | null): number {
  const wanted = requested ? Number(requested) : DEFAULT_DONATION;
  if (amounts.includes(wanted)) return wanted;
  if (amounts.includes(DEFAULT_DONATION)) return DEFAULT_DONATION;
  return amounts[Math.floor(amounts.length / 2)];
}

/** Interpret a boolean attribute: present and not "false". */
export function isFlagOn(attr: string | null): boolean {
  return attr !== null && attr.trim().toLowerCase() !== 'false';
}
