import type { SupabaseClient } from '@supabase/supabase-js';
import { DwRecentDonations, type RecentQuery } from '../../oss/donation-widgets/src/recent-donations';
import { getSupabaseClient } from '../common/supabase-client';
import { campaignOrFilter, campaignRealtimeFilters, parseCampaignId } from '../common/campaign-filters';

/**
 * <rg-recent-donations campaign-id="…">: the latest donations, optionally for one campaign
 * (its own plus the ones rolled up into it). Without `campaign-id` it shows every donation.
 */
export class RgRecentDonations extends DwRecentDonations {
  static get observedAttributes(): string[] {
    return [...super.observedAttributes, 'campaign-id'];
  }

  protected override recentQuery(query: RecentQuery): RecentQuery {
    const id = parseCampaignId(this.getAttribute('campaign-id'));
    return id ? query.or(campaignOrFilter(id)) : query;
  }

  protected override realtimeFilters(): string[] {
    return campaignRealtimeFilters(parseCampaignId(this.getAttribute('campaign-id')));
  }

  /** A campaign widget hears about full refunds (deletions) too. */
  protected override watchDeletes(): boolean {
    return parseCampaignId(this.getAttribute('campaign-id')) !== null;
  }

  /** The page's one shared client (one realtime socket). Also validates `campaign-id` up front. */
  protected override getSupabase(): SupabaseClient {
    parseCampaignId(this.getAttribute('campaign-id'));
    return getSupabaseClient();
  }
}
