import { escapeHtml, formatCurrency } from './lib/format';

// The leaderboard's pure rendering and query helpers (no DOM, so they can be unit-tested).

export interface LeaderboardRow {
  display_name: string;
  total_usd: number | null;
  total_original: number | null;
  original_currency: string | null;
}

function medal(rank: number): string {
  if (rank === 1) return '<span aria-label="1st place">🥇</span>';
  if (rank === 2) return '<span aria-label="2nd place">🥈</span>';
  if (rank === 3) return '<span aria-label="3rd place">🥉</span>';
  return `<span class="lb-rank-num" aria-label="rank ${rank}">#${rank}</span>`;
}

/** The start of a timeframe as an ISO timestamp, or null for "all time". */
export function cutoffFor(days: number, now: number = Date.now()): string | null {
  return days === 0 ? null : new Date(now - days * 86_400_000).toISOString();
}

/** Arguments of the `leaderboard_rankings` function: the core ones, then a subclass's extras. */
export function rankingArgs(
  days: number,
  limit: number,
  extra: Record<string, unknown> = {},
  now: number = Date.now(),
): Record<string, unknown> {
  return { cutoff_ts: cutoffFor(days, now), row_limit: limit, ...extra };
}

export function renderLeaderboardRows(rows: LeaderboardRow[] | null): string {
  if (!rows || !rows.length) {
    return '<li class="lb-state">No donations yet in this period — be the first! 🎉</li>';
  }
  return rows
    .map((row, i) => {
      const rank = i + 1;
      const currency = (row.original_currency || 'usd').toLowerCase();
      const usdNote =
        currency === 'usd' ? '' : `<span class="lb-usd-note">≈ ${formatCurrency(row.total_usd ?? 0, 'usd')}</span>`;
      return (
        `<li class="lb-item lb-rank-${Math.min(rank, 4)}" style="animation-delay:${i * 55}ms">` +
        `<span class="lb-medal">${medal(rank)}</span>` +
        `<span class="lb-name">${escapeHtml(row.display_name)}</span>` +
        `<span class="lb-amount">${formatCurrency(row.total_original ?? 0, currency)}${usdNote}</span>` +
        `</li>`
      );
    })
    .join('');
}
