import { escapeHtml, formatCurrency, timeAgo } from './lib/format';

// The recent-donations feed's pure rendering helpers (no DOM, so they can be unit-tested).

export interface RecentRow {
  name: string;
  original_amount: number;
  original_currency: string | null;
  amount_usd: number;
  stripe_subscription_id: string | null;
  created_at: string;
}

export const RECENT_COLUMNS = 'name, original_amount, original_currency, amount_usd, stripe_subscription_id, created_at';
export function renderRecentRows(rows: RecentRow[] | null, now: number = Date.now()): string {
  if (!rows || !rows.length) return '<li class="rd-state">No donations yet — be the first! 🎉</li>';
  return rows
    .map((row, i) => {
      const currency = (row.original_currency || 'usd').toLowerCase();
      const usdNote =
        currency === 'usd' ? '' : `<span class="rd-usd-note">≈ ${formatCurrency(row.amount_usd, 'usd')}</span>`;
      const recurBadge = row.stripe_subscription_id
        ? '<span class="rd-recur-badge" title="Recurring donation">↻</span>'
        : '';
      return (
        `<li class="rd-item" style="animation-delay:${i * 55}ms">` +
        `<span class="rd-dot" aria-hidden="true"></span>` +
        `<span class="rd-main">` +
        `<span class="rd-name">${escapeHtml(row.name)}${recurBadge}</span>` +
        `<span class="rd-time">${timeAgo(row.created_at, now)}</span>` +
        `</span>` +
        `<span class="rd-amount">${formatCurrency(row.original_amount, currency)}${usdNote}</span>` +
        `</li>`
      );
    })
    .join('');
}
